import{_ as t,c as a,o,ag as n}from"./chunks/framework.DZ_cNctr.js";const m=JSON.parse('{"title":"Annotation Templates — Find Nuclei Viewer","description":"Create reusable annotation templates — a named bundle of color + class + keyboard shortcut that auto-applies to every annotation you draw. Manage default and custom templates; share template sets via URL state.","frontmatter":{"title":"Annotation Templates — Find Nuclei Viewer","description":"Create reusable annotation templates — a named bundle of color + class + keyboard shortcut that auto-applies to every annotation you draw. Manage default and custom templates; share template sets via URL state."},"headers":[],"relativePath":"guides/templates.md","filePath":"guides/templates.md"}'),s={name:"guides/templates.md"};function l(r,e,i,c,d,p){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="annotation-templates" tabindex="-1">Annotation Templates <a class="header-anchor" href="#annotation-templates" aria-label="Permalink to &quot;Annotation Templates&quot;">​</a></h1><p>Templates are reusable annotation configurations — each one bundles a <strong>color</strong>, a <strong>class</strong> label, optional extra metadata, and a <strong>keyboard shortcut slot</strong>. While a template is active, every annotation you draw inherits its settings automatically.</p><p>If you catch yourself repeatedly drawing &quot;tumor → red → class: tumor&quot; or &quot;blood vessel → pink → class: vessel&quot;, you want templates.</p><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>templates-in-action.png</code> — A slide with annotations drawn in multiple colors, the Annotations panel sidebar showing the list grouped by class, and the Template Manager modal open in the foreground. </div><h2 id="default-templates" tabindex="-1">Default templates <a class="header-anchor" href="#default-templates" aria-label="Permalink to &quot;Default templates&quot;">​</a></h2><p>Find Nuclei Viewer ships with a handful of sensible defaults: <code>Tumor</code>, <code>Stroma</code>, <code>Necrosis</code>, <code>Immune</code>, <code>Normal</code>, <code>ROI</code>. Each has a reserved keyboard shortcut (<code>Alt+1</code> through <code>Alt+6</code>) and a curated color.</p><p>You can use them as-is, edit them, delete them, or add your own. Edits and additions persist per browser and survive reloads.</p><h2 id="template-manager" tabindex="-1">Template Manager <a class="header-anchor" href="#template-manager" aria-label="Permalink to &quot;Template Manager&quot;">​</a></h2><p>Click <strong>Templates</strong> in the Annotations panel toolbar to open the Template Manager modal:</p><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>templates-manager-modal.png</code> — Template Manager modal: list of templates as rows with color swatch, name input, class input, shortcut number, and a delete button. &quot;Add template&quot; button at the bottom. </div><p>Each row has:</p><ul><li><strong>Color swatch</strong> — click to pick from the preset grid or type hex / RGB</li><li><strong>Name</strong> — the display name that appears in the on-canvas chip row and the Annotations toolbar dropdown</li><li><strong>Class</strong> — the value stored in <code>keyValues.class</code> on every annotation drawn with this template. Also drives the annotation list&#39;s default grouping.</li><li><strong>Shortcut</strong> — the <code>Alt+N</code> slot (1–9). Blank = no shortcut.</li><li><strong>Delete</strong> — remove this template (annotations already drawn with it keep their class + color; only the template is removed from your set).</li></ul><p>At the bottom of the modal:</p><ul><li><strong>Add template</strong> — append an empty row to create a new one</li><li><strong>Save</strong> / <strong>Cancel</strong> — commit or discard your changes</li></ul><h2 id="applying-a-template" tabindex="-1">Applying a template <a class="header-anchor" href="#applying-a-template" aria-label="Permalink to &quot;Applying a template&quot;">​</a></h2><p>There are three ways to apply a template to an annotation.</p><h3 id="_1-pick-one-then-draw" tabindex="-1">1. Pick one, then draw <a class="header-anchor" href="#_1-pick-one-then-draw" aria-label="Permalink to &quot;1. Pick one, then draw&quot;">​</a></h3><p>With a drawing tool active (Polygon, Line, Point, etc.), an on-canvas chip row appears showing every template as a color chip. Click one to set it as active. Every annotation you create next inherits that template.</p><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>templates-on-canvas-picker.png</code> — On-canvas template chip row at the top of the image: colored chips with names, one chip highlighted / active. </div><p>The chip you picked stays active until you pick another, clear the active template (click the same chip twice), or switch tools.</p><h3 id="_2-keyboard-shortcuts" tabindex="-1">2. Keyboard shortcuts <a class="header-anchor" href="#_2-keyboard-shortcuts" aria-label="Permalink to &quot;2. Keyboard shortcuts&quot;">​</a></h3><p>Templates with an assigned <code>Alt+N</code> shortcut can be activated without touching the chip row. Press <code>Alt+1</code> through <code>Alt+9</code> to flip the active template; the on-canvas chip row updates so you can see which one is live.</p><p>Shortcuts are global while any annotation drawing tool is active — they don&#39;t interfere with form inputs or other keyboard handlers.</p><h3 id="_3-re-template-an-existing-annotation" tabindex="-1">3. Re-template an existing annotation <a class="header-anchor" href="#_3-re-template-an-existing-annotation" aria-label="Permalink to &quot;3. Re-template an existing annotation&quot;">​</a></h3><p>Select an annotation, click its color swatch. The swatch popover opens with a <strong>Template</strong> dropdown at the top:</p><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>templates-swatch-dropdown.png</code> — Annotation swatch popover open, Template dropdown at top with options visible, Opacity slider below, Render toggles, ColorPicker presets below. </div><p>Pick a template and the annotation&#39;s color, <code>class</code> key-value, and — if its label contains the previous template&#39;s name — its label itself update in one step (<code>Tumor 1</code> → <code>Stroma 1</code>). The list reorders into the new class group and the canvas smoothly zooms so you don&#39;t lose track.</p><h3 id="_4-bulk-apply-to-many-annotations" tabindex="-1">4. Bulk-apply to many annotations <a class="header-anchor" href="#_4-bulk-apply-to-many-annotations" aria-label="Permalink to &quot;4. Bulk-apply to many annotations&quot;">​</a></h3><p>Select several annotations (list multi-select or canvas lasso), then pick a template from the <strong>bulk action bar&#39;s Template dropdown</strong>. Every selected annotation is reclassified in a single undoable step.</p><h2 id="label-substitution-—-how-it-works" tabindex="-1">Label substitution — how it works <a class="header-anchor" href="#label-substitution-—-how-it-works" aria-label="Permalink to &quot;Label substitution — how it works&quot;">​</a></h2><p>When you re-template an annotation, the viewer looks at the annotation&#39;s current label. If the label starts with the old template&#39;s name (e.g., <code>Tumor 5</code>), the substitution replaces just the name portion: <code>Tumor 5</code> → <code>Stroma 5</code>.</p><p>Annotations with custom labels (<code>my cell of interest</code>) are left untouched — the substitution only fires on auto-generated names. Labels like <code>Tumor apex</code> also get the prefix swapped to <code>Stroma apex</code> because the template name is the leading word.</p><h2 id="conventions-we-recommend" tabindex="-1">Conventions we recommend <a class="header-anchor" href="#conventions-we-recommend" aria-label="Permalink to &quot;Conventions we recommend&quot;">​</a></h2><ul><li><strong>Keep class values lowercase, single-word</strong>. <code>tumor</code>, <code>stroma</code>, <code>necrosis</code>. This keeps URL state compact and pairs well with downstream CSV export where <code>class</code> often becomes a column header.</li><li><strong>Keep template names human-readable</strong>. <code>Tumor</code>, <code>Stroma</code>, <code>Blood vessel</code>. The name shows in the chip row and legends; class is the machine-readable identifier.</li><li><strong>Use shortcuts sparingly</strong>. Assign <code>Alt+1..4</code> to the three or four you use constantly. The rest can live in the dropdown — you&#39;ll reach for them rarely and the Alt+5..9 slots stay clean.</li><li><strong>One template per class</strong>. Multiple templates with the same class value confuse the legend and the detail panel. If you need variations, use key-values (e.g., <code>class: tumor, grade: G1</code>) rather than parallel templates.</li></ul><h2 id="persistence-and-sharing" tabindex="-1">Persistence and sharing <a class="header-anchor" href="#persistence-and-sharing" aria-label="Permalink to &quot;Persistence and sharing&quot;">​</a></h2><p>Templates persist in your browser&#39;s IndexedDB, keyed by installation (not by image). Opening any image in the same browser picks up your customisations.</p><p>The <strong>URL state</strong> carries the active-template ID when you share a link, so a reviewer opening your link sees the same template pre-selected. The full template set itself doesn&#39;t travel in the URL — if you send a link to someone who&#39;s never customised templates, they see the defaults. This is by design: templates are your personal preset bank, not per-image configuration.</p><div class="tip custom-block"><p class="custom-block-title">Sharing a custom template set</p><p>If you need teammates to use your custom templates, the easiest path today is a screenshot of the Template Manager for them to recreate. A template import / export feature is on the roadmap.</p></div><h2 id="mobile" tabindex="-1">Mobile <a class="header-anchor" href="#mobile" aria-label="Permalink to &quot;Mobile&quot;">​</a></h2><p>Template Manager and the on-canvas chip row both work on touch devices, but the drawing tools that activate them are primarily desktop / tablet workflows. On phone viewports the Annotations tab is read-only.</p><h2 id="related-guides" tabindex="-1">Related guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related guides&quot;">​</a></h2><ul><li><a href="./annotations.html">Annotations</a> — the full annotation workflow</li><li><a href="./sharing.html">Sharing Views</a> — URL state captures the active template</li></ul>',42)])])}const u=t(s,[["render",l]]);export{m as __pageData,u as default};
